import {ToolRegistry} from './registry.js';

function registerWeatherTool(
  registry: ToolRegistry,
  execute: (input: Record<string, unknown>) => Promise<string>
): void {
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    execute
  );
}

describe('ToolRegistry schema caching', () => {
  it('throws for an unknown tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('returns a required-field rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registerWeatherTool(registry, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('weather', {});

    expect({
      mentionsRequiredField: /location.*required|required.*location/i.test(response.result),
      executorCalls,
    }).toEqual({mentionsRequiredField: true, executorCalls: 0});
  });

  it('rejects a wrong-typed field with its path and expected type without echoing the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registerWeatherTool(registry, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const response = await registry.execute('weather', {location: 8675309});

    expect({
      namesFieldAndType: /location.*string|string.*location/i.test(response.result),
      leaksValue: response.result.includes('8675309'),
      executorCalls,
    }).toEqual({namesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });

  it('reports a nested wrong-typed field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', properties: {city: {type: 'string'}}}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {city: 8675309}});

    expect(response.result).toMatch(/location\.city.*string|string.*location\.city/i);
  });

  it('compiles a static schema once and reuses it across ten executions', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const definition = {
      name: 'weather',
      description: 'Weather',
      get inputSchema() {
        schemaReads += 1;
        return {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      },
    };
    let executorCalls = 0;
    registry.register(definition, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    const responses = await Promise.all(
      Array.from({length: 10}, () => registry.execute('weather', {location: 'Berlin'}))
    );

    expect({schemaReads, executorCalls, results: responses.map(response => response.result)}).toEqual({
      schemaReads: 1,
      executorCalls: 10,
      results: Array(10).fill('sunny'),
    });
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', extra: 'kept'};
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async value => {
        received.push(value);
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', input);

    expect({response: response.result, received}).toEqual({response: 'sunny', received: [input]});
  });

  it('validates function definitions against the schema resolved for each call', async () => {
    let definitionCalls = 0;
    const executedInputs: Array<Record<string, unknown>> = [];
    const registry = new ToolRegistry();

    registry.register(
      () => {
        definitionCalls += 1;
        const field = definitionCalls <= 2 ? 'city' : 'count';
        const type = definitionCalls <= 2 ? 'string' : 'number';
        return {
          name: 'changing_tool',
          description: 'Uses a per-call input schema',
          inputSchema: {type: 'object', properties: {[field]: {type}}, required: [field]},
        };
      },
      async input => {
        executedInputs.push(input);
        return 'accepted';
      }
    );

    const firstResponse = await registry.execute('changing_tool', {city: 'Berlin'});
    const secondResponse = await registry.execute('changing_tool', {city: 'Berlin'});

    expect({
      firstResult: firstResponse.result,
      secondResult: secondResponse.result,
      definitionCalls,
      executedInputs,
    }).toEqual({
      firstResult: 'accepted',
      secondResult: expect.stringMatching(/count.*required|required.*count/i),
      definitionCalls: 3,
      executedInputs: [{city: 'Berlin'}],
    });
  });
});
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

type ValidationIssue = {keyword: string; instancePath?: string; dataPath?: string; params: Record<string, unknown>};

const ajv = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<typeof Ajv>[0]);
const dynamicValidators = new WeakMap<object, ValidateFunction>();

function formatValidationError(error: ValidationIssue): string {
  const path = errorPath(error.instancePath);
  if (error.keyword === 'required') {
    const property = error.params.missingProperty as string;
    return `Input property ${[...path, property].join('.')} is required`;
  }
  if (error.keyword === 'type') {
    const expected = error.params.type as string;
    return `Input property ${path.join('.') || 'input'} must be ${expected}`;
  }
  return `Input ${path.length ? `property ${path.join('.')}` : 'does not'} satisfy constraint ${error.keyword}`;
}

function errorPath(instancePath: string | undefined): string[] {
  const parts = (instancePath ?? '').split('/').filter(Boolean);
  return parts.map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
}

function legacyErrorPath(dataPath: string | undefined): string[] {
  return (dataPath ?? '').replace(/^\./, '').split('.').filter(Boolean);
}

function normalizeValidationErrorPath(error: ValidationIssue): ValidationIssue {
  if (error.instancePath || !error.dataPath) return error;
  return {...error, instancePath: `/${legacyErrorPath(error.dataPath).join('/')}`};
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.compile(resolved.inputSchema);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${message}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compile(schema: object): ValidateFunction {
    const cached = dynamicValidators.get(schema);
    if (cached) return cached;
    const validator = ajv.compile(schema);
    dynamicValidators.set(schema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as tool results; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.compile(definition.inputSchema);
    if (!validator(input)) {
      const errors = (validator.errors ?? []).map(error => ({
        keyword: error.keyword,
        instancePath: (error as typeof error & {instancePath?: string}).instancePath,
        dataPath: (error as typeof error & {dataPath?: string}).dataPath,
        params: {...error.params},
      })).map(normalizeValidationErrorPath);
      return {result: errors.map(formatValidationError).join('; ')};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

